(async()=>{'use strict';
const root=document.querySelector('#root'),base='/api/m/novel-studio/';
const E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={world:'世界事实',belief:'角色信念',speech:'人物话语',plan:'计划',unknown:'未分类'};
let resultTab='manuscript',inspectedStage='',inspectorTab='output',canvasZoom=1,briefCollapsed=typeof matchMedia==='function'&&matchMedia('(max-width:760px)').matches;
const openDetails=new Set();
let account='', archive=null, version=0, projectId='', sceneId='', busy=false, pending=null, preview=null, previewInput=null, candidate=null, review=null, checked=new Set(), events=[], runs={preview:'idle',draft:'idle',review:'idle',apply:'idle'};
let form={instruction:'',moment:'',perspective:'omniscient',pov:'',factIds:[],model:'',idea:'',writer:'',extract:'',reviewPrompt:'',projectName:'',sceneTitle:'',sceneCount:1,scenePlans:'',plannerPrompt:'',runMode:'idea'};
let availableModels=[],modelsStatus='正在读取模型列表…',modelsTruncated=false,modelRefreshSequence=0,modelSourceRevision=null;
let plannerStatus='idle',ideaPreview=null,ideaPreviewInput=null,planPreview=null,planPreviewInput=null,planResult=null,defaultModel='', auto={status:'idle',stages:[],messages:[],draft:'',candidates:[],issues:[],scenes:[],notice:''};
const project=()=>archive?.projects.find(p=>p.id===projectId);const scene=()=>project()?.scenes.find(s=>s.id===sceneId);const revision=()=>scene()?.revisions.at(-1);
const sessionKey=()=>`novel-canvas-pending:${account}`;
const time=()=>new Date().toLocaleTimeString('zh-CN',{hour12:false});
function log(message){events.unshift({time:time(),message});if(events.length>100)events.pop()}
function toast(message){let old=document.querySelector('.toast');old?.remove();let d=document.createElement('div');d.className='toast';d.setAttribute('role','status');d.textContent=message;document.body.append(d);setTimeout(()=>d.remove(),5000)}
function headers(){return {'Content-Type':'application/json','X-Hub-User-Id':account}}
function draftMatches(s,r){return !!r&&s?.title===r.title&&s?.draft===r.body}
function sameInput(){if(!previewInput||!revision())return false;return JSON.stringify({projectId,sceneId,revisionId:revision().id,instruction:form.instruction.trim(),storyMoment:form.moment.trim(),perspective:form.perspective,pov:form.pov.trim(),factIds:form.factIds,model:form.model.trim()})===JSON.stringify(previewInput)}
function invalidate(){preview=null;previewInput=null;candidate=null;review=null;checked=new Set();runs={preview:'idle',draft:'idle',review:'idle',apply:'idle'}}
async function load(){let r=await fetch(base+'canon',{cache:'no-store',headers:{'X-Hub-User-Id':account}}),d=await r.json().catch(()=>null);if(!r.ok||!d?.state||!Array.isArray(d.state.projects)||!Number.isSafeInteger(d.version))throw Error(d?.error||'无法读取服务端档案');archive=d.state;version=d.version;if(!archive.projects.some(x=>x.id===projectId))projectId=archive.projects[0]?.id||'';if(!project()?.scenes.some(x=>x.id===sceneId))sceneId=project()?.scenes[0]?.id||''}
async function request(endpoint,input,label){let response;try{const task=fetch(base+endpoint,{method:'POST',headers:headers(),body:JSON.stringify(input)});log(`${label}：已发起请求`);render();response=await task}catch{const model=endpoint==='draft'||endpoint==='review';log(`${label}：未取得服务端响应${model?'，结果未知':''}`);const err=Error(model?'未收到响应，模型是否已执行或产生费用无法确认；不会自动重试。':'未取得服务端响应，请手动重试。');if(model)err.unknown=true;throw err}let result=await response.json().catch(()=>null);log(`${label}：收到 HTTP ${response.status}`);if(!response.ok){const maybeModel=(endpoint==='draft'||endpoint==='review')&&([408,409,429].includes(response.status)||response.status>=500)&&!(response.status===503&&(result?.error||'').includes('尚未配置'));const err=Error((result?.error||`请求失败（HTTP ${response.status}）`)+(maybeModel?' 模型是否已执行或产生费用无法确认，不会自动重试。':''));if(maybeModel)err.unknown=true;throw err;}if(!result||result.status!=='REVIEW'){const err=Error((endpoint==='draft'||endpoint==='review')?'响应格式无效；模型可能已执行或产生费用，不会自动重试。':'预览响应格式无效。');if(endpoint==='draft'||endpoint==='review')err.unknown=true;throw err;}return result}
function modelOptions(value){const ids=availableModels.map(x=>x.id);const custom=value&&!ids.includes(value);return `<option value="">使用默认模型${defaultModel?' · '+E(defaultModel):''}</option>${availableModels.map(x=>`<option value="${E(x.id)}">${E(x.id)}</option>`).join('')}${custom?`<option value="${E(value)}">手动输入 · ${E(value)}</option>`:''}<option value="__manual__">手动输入其他模型…</option>`}
function modelControl(id,value){return `<div class="model-control"><label class="field">写作模型<select data-model-picker="${E(id)}" aria-label="选择模型">${modelOptions(value).replace(`value="${E(value)}"`, `value="${E(value)}" selected`)}</select></label><div class="model-links"><a href="model-settings.html" target="_blank" rel="noopener">模型设置</a><button class="text-button" type="button" data-act="refresh-models">刷新</button></div><details class="model-advanced" data-detail-key="model-advanced"><summary>其他模型</summary><label class="field">模型名称<input id="${E(id)}" maxlength="101" value="${E(value)}" placeholder="留空使用默认模型"></label><p class="small" data-model-status>${E(modelsStatus)}${modelsTruncated?'（列表未全部返回）':''}；是否支持写作需实际验证。</p></details></div>`}
function syncModelControls(){for(const el of document.querySelectorAll('[data-model-picker]')){const input=document.getElementById(el.dataset.modelPicker),value=input?.value??form.model;el.innerHTML=modelOptions(value);el.value=value||''}for(const el of document.querySelectorAll('[data-model-status]'))el.textContent=modelsStatus+(modelsTruncated?'（列表未全部返回）':'')+'；列表仅表示 API 返回，是否支持写作需实际验证。';const label=document.querySelector('[data-effective-model]');if(label)label.textContent=auto.requestModel||form.model||defaultModel||'尚未选择模型'}
async function refreshModels(){const seq=++modelRefreshSequence;let previous=defaultModel;try{const pr=await fetch(base+'model-preference',{cache:'no-store',headers:{'X-Hub-User-Id':account}}),pd=await pr.json().catch(()=>null);if(seq!==modelRefreshSequence)return;if(pr.status===409)defaultModel='';else if(pr.ok&&pd){let next=pd.model||pd.fallbackModel;if(typeof next==='string')defaultModel=next}}catch{}if(previous!==defaultModel&&!form.model.trim()){previewInput=null;ideaPreview=null;ideaPreviewInput=null;planPreview=null;planPreviewInput=null;for(const b of document.querySelectorAll('[data-act="draft"],[data-act="review"],[data-act="apply"],[data-act="auto-run"],[data-act="plan-run"]'))b.disabled=true;let note=document.querySelector('#context-safety');if(note){note.textContent='默认模型已变化，请重新预览。';note.className='note warn'}}try{const r=await fetch(base+'models',{cache:'no-store',headers:{'X-Hub-User-Id':account}}),d=await r.json().catch(()=>null);if(seq!==modelRefreshSequence)return;if(!r.ok||!Array.isArray(d?.models))throw Error(d?.error||'模型列表暂不可用');if(Number.isSafeInteger(d.sourceRevision)){if(modelSourceRevision!==null&&modelSourceRevision!==d.sourceRevision){previewInput=null;ideaPreview=null;ideaPreviewInput=null;planPreview=null;planPreviewInput=null;for(const b of document.querySelectorAll('[data-act="draft"],[data-act="review"],[data-act="apply"],[data-act="auto-run"],[data-act="plan-run"]'))b.disabled=true;let note=document.querySelector('#context-safety');if(note){note.textContent='模型连接已变化，请重新预览。';note.className='note warn'}}modelSourceRevision=d.sourceRevision}availableModels=(Array.isArray(d.writingModels)?d.writingModels:d.models).filter(x=>x&&typeof x.id==='string');modelsTruncated=!!d.truncated;modelsStatus=availableModels.length?`已读取 ${availableModels.length} 个模型`:'连接返回空模型列表';}catch(e){if(seq!==modelRefreshSequence)return;availableModels=[];modelsTruncated=false;modelsStatus=e.message||'模型列表暂不可用，可手动输入';}syncModelControls()}
function step(label,state,detail){return `<div class="node ${E(state)}"><span class="step">${E(label)}</span><strong>${E(detail[0])}</strong><span class="state">${E(detail[1])}</span></div>`}
const statusText=s=>({idle:'尚未开始',running:'请求中',complete:'已收到结果',failed:'请求失败',unknown:'结果未知'})[s]||'尚未开始';
function view(){
  const content=`<div class="canvas-page">${pending?'<div class="note warn recovery" role="status">上次保存的结果尚未确认。<button data-act="retry">恢复待确认操作</button><details><summary>了解恢复</summary>重试会沿用原来的操作，不重复创建。恢复记录保存在当前页签，可能包含候选正文。</details></div>':''}<div class="writing-desk ${briefCollapsed?'brief-collapsed':''}"><section class="brief-panel" aria-labelledby="brief-title">${ideaPanel()}</section><section class="canvas-work" aria-label="创作执行与结果">${executionCanvas()}${resultsPanel()}${eventHistory()}</section></div></div>`;
  return studioShell(content);
}
function studioShell(content){return window.NovelStudio?.shell?window.NovelStudio.shell({active:'canvas',title:'创作画布',content,actions:'<a class="canvas-header-link" href="model-settings.html" target="_blank" rel="noopener">模型设置</a>'}):`<main class="canvas-standalone"><h1>创作画布</h1>${content}</main>`}
function sceneContext(){const p=project(),s=scene(),r=revision(),valid=!!r&&draftMatches(s,r);return `<div class="context-selects"><label class="field">作品<select id="project">${(archive?.projects||[]).map(x=>`<option value="${E(x.id)}" ${x.id===projectId?'selected':''}>${E(x.name)}</option>`).join('')||'<option value="">还没有作品</option>'}</select></label><label class="field">场景<select id="scene">${(p?.scenes||[]).map(x=>`<option value="${E(x.id)}" ${x.id===sceneId?'selected':''}>${E(x.title)}</option>`).join('')||'<option value="">还没有场景</option>'}</select></label></div>${!valid?`<div class="note">${s?'请先保存当前正文版本，再从这里续写。':'先创建作品与场景，或切换到「新建故事」。'} <a href="consistency.html?view=write">打开正文编辑</a></div>`:''}<label class="field">这一次想写什么<textarea id="instruction" maxlength="2000" placeholder="接下来会发生什么？希望人物做出怎样的选择？">${E(form.instruction)}</textarea></label><div class="field-pair"><label class="field">故事时点<input id="moment" value="${E(form.moment)}" placeholder="如 3 或 3.5" inputmode="decimal"></label><label class="field">叙事视角<select id="perspective"><option value="omniscient" ${form.perspective==='omniscient'?'selected':''}>全知视角</option><option value="limited" ${form.perspective==='limited'?'selected':''}>人物限知</option></select></label></div>${form.perspective==='limited'?`<label class="field">视角人物<input id="pov" maxlength="120" value="${E(form.pov)}" placeholder="角色标识，如 lin_yu"></label>`:''}<details class="context-facts" data-detail-key="context-facts"><summary>参考事实${form.factIds.length?` · 已选 ${form.factIds.length} 条`:''}</summary><p class="small">只选择此时点、此视角已经知道的事实，最多 40 条。</p><div class="checks">${(p?.facts||[]).map(f=>`<label class="check"><input type="checkbox" data-fact="${E(f.id)}" ${form.factIds.includes(f.id)?'checked':''}><span>${E(f.statement)}<small>${E(names[f.layer]||f.layer)}${f.storyTime?' · '+E(f.storyTime):''}</small></span></label>`).join('')||'<p class="small">尚未确认事实。可先续写，再审阅生成的内容。</p>'}</div></details>`}
function promptEditors(){return `<div class="prompt-editors"><label class="field">写作提示词<textarea id="idea-writer" maxlength="2000" placeholder="风格、叙事节奏、篇幅与语言偏好">${E(form.writer)}</textarea></label><label class="field">事实抽取提示词<textarea id="idea-extract" maxlength="2000" placeholder="重点提取人物、物品、时间或世界规则">${E(form.extract)}</textarea></label><label class="field">审阅提示词<textarea id="idea-review" maxlength="2000" placeholder="重点检查人物行为、设定或时间关系">${E(form.reviewPrompt)}</textarea></label><p class="small">这些指导会加入模型输入。预览可查看完整内容。</p></div>`}
function planningPanel(){return `<details class="planning" data-detail-key="planning"><summary>场景计划</summary><label class="field">每行一个场景<textarea id="idea-plans" maxlength="7500" placeholder="第一幕：陌生的来信&#10;第二幕：决定启程">${E(form.scenePlans)}</textarea></label>${form.runMode==='idea'?`<details data-detail-key="planner"><summary>让 AI 帮我规划</summary><label class="field">规划要求<textarea id="planner-prompt" maxlength="2000" placeholder="如：前两幕逐渐揭示悬念">${E(form.plannerPrompt)}</textarea></label><div class="actions"><button data-act="plan-preview" ${busy||pending?'disabled':''}>查看规划提示词</button><button data-act="plan-run" ${busy||pending||!planPreview?'disabled':''}>生成计划</button></div>${planPreview?`<details open><summary>规划输入</summary>${messagesView(planPreview.messages)}</details>`:''}${planResult?`<ol class="plan-list">${(planResult.scenes||[]).map(x=>`<li><strong>${E(x.title)}</strong><p>${E(x.goal)}</p></li>`).join('')}</ol><button data-act="plan-apply">采用计划</button><p class="small">${E(planResult.model||'未提供模型名称')}</p>`:''}<p class="small">生成计划会额外调用一次模型。</p></details>`:''}</details>`}
function messagesView(messages){return (messages||[]).map(m=>`<article class="prompt-message"><span class="message-role">${E(({system:'系统规则',user:'创作要求',assistant:'前文参考'})[m.role]||m.role)}</span><div class="text">${E(m.content)}</div></article>`).join('')||'<p class="small">尚无模型输入。</p>'}
function hasCreativeBrief(){return form.runMode==='scene'?!!form.instruction.trim():!!form.idea.trim()}
function adoptedCurrentPlan(){let current=false;try{current=!!planResult&&!!planPreview&&JSON.stringify(planPayload())===JSON.stringify(planPreviewInput)}catch{}return current&&form.scenePlans.trim()===planResult.scenes.map(x=>`${x.title}：${x.goal}`.replace(/[\r\n]+/g,' ')).join('\n').trim()}
function executionCanvas(){
  const actual=auto.stages||[],count=Number(auto.sceneCount)||Number(form.sceneCount)||1;
  const statusFor=kind=>{const matches=actual.filter(x=>x.kind===kind),last=matches.at(-1);return last?{state:matches.some(x=>x.status==='running')?'running':last.status,detail:last.status==='complete'?`已完成 ${matches.filter(x=>x.status==='complete').length} / ${count} 幕`:last.detail}:((kind==='draft'||kind==='review')&&runs[kind]!=='idle'?{state:runs[kind],detail:statusText(runs[kind])}:{state:'idle',detail:'尚未调用'})};
  const prep=auto.status!=='idle'||ideaPreview||preview?'complete':'idle';
  let currentPlan=false;try{currentPlan=!!planPreview&&JSON.stringify(planPayload())===JSON.stringify(planPreviewInput)}catch{}const plan=plannerStatus==='running'?'running':plannerStatus==='failed'?'failed':(planResult||planPreview)&&!currentPlan?'stale':planResult?'complete':planPreview?'ready':'skipped';
  const draft=statusFor('draft'),extract=statusFor('extract'),check=statusFor('review');
  const planAdopted=auto.status!=='idle'&&typeof auto.usedPlan==='boolean'?auto.usedPlan:adoptedCurrentPlan();
  const plannedHere=currentPlan&&!!planResult;
  const plannerInputState=plannerStatus==='running'?'running':plannedHere?'complete':'idle';
  const save=auto.saved||runs.apply==='complete'?'complete':runs.apply==='running'?'running':pending?'unknown':auto.draft?'ready':'idle';
  const nodes=[
    {id:'prepare',title:'创作构思',state:prep,detail:prep==='complete'?'输入已准备':form.runMode==='scene'?'从现有场景续写':'从一个想法开始',x:30,y:38,icon:'idea'},
    {id:'plan',title:'场景规划',state:plan,detail:plannerStatus==='running'?'正在生成计划':plannerStatus==='failed'?'规划未完成':plan==='stale'?'构思已变，请重新规划':planResult?(planAdopted?`已采用 ${planResult.scenes?.length||0} 幕计划`:'已生成，等待采用'):planPreview?'已预览，尚未调用':'可选 · 尚未调用',x:260,y:38,icon:'plan'},
    {id:'draft',title:'正文生成',...draft,x:490,y:38,icon:'draft'},
    {id:'extract',title:'事实提取',...extract,x:490,y:246,icon:'extract'},
    {id:'review',title:'独立审阅',...check,x:260,y:246,icon:'review'},
    {id:'save',title:'保存作品',state:save,detail:auto.saved||runs.apply==='complete'?'草稿已保存':pending?'保存结果待确认':auto.draft?'等待你确认':'等待生成结果',x:30,y:246,icon:'save'}
  ];
  const summary=auto.status==='complete'?'等待审阅':auto.status==='running'?'正在创作':auto.status==='unknown'?'结果未知':auto.status==='failed'?'创作未完成':ideaPreview?'输入已准备':'准备创作';
  const arrow=(name,path,state,optional=false)=>`<path class="graph-edge ${E(state||'idle')}${optional?' optional':''}" d="${path}" marker-end="url(#arrow-${state==='complete'?'complete':state==='running'?'running':'idle'})" data-edge="${name}"/>`;
  return `<section class="execution-panel"><div class="section-title canvas-toolbar ${briefCollapsed?'has-primary':''}"><div class="canvas-title"><h2>执行画布</h2><span class="run-status ${auto.status==='running'?'is-running':''}" role="status">${E(summary)}</span></div>${briefCollapsed?`<button class="primary canvas-primary" data-act="canvas-primary" ${busy||pending?'disabled':''}>${busy?'正在创作…':hasCreativeBrief()?'开始创作':form.runMode==='scene'?'填写续写要求':'填写构思'}</button>`: ''}<div class="canvas-controls"><button class="text-button" data-act="toggle-brief" aria-expanded="${!briefCollapsed}">${briefCollapsed?'展开设置':'收起设置'}</button><div class="zoom-controls"><button data-act="zoom-out" aria-label="缩小画布" title="缩小">−</button><span>${Math.round(canvasZoom*100)}%</span><button data-act="zoom-in" aria-label="放大画布" title="放大">+</button><button data-act="zoom-fit" title="适应画布" aria-label="适应画布">适应</button></div></div></div><div class="graph-viewport" tabindex="0" role="region" aria-label="创作流程画布，可滚动查看节点"><div class="graph-size" style="width:${700*canvasZoom}px;height:${424*canvasZoom}px"><div class="graph-plane" style="transform:scale(${canvasZoom})"><svg class="graph-connectors" width="700" height="424" viewBox="0 0 700 424" fill="none" aria-hidden="true"><defs>${['idle','complete','running'].map(st=>`<marker id="arrow-${st}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M1 1 7 4 1 7" class="arrow-tip ${st}"/></marker>`).join('')}</defs>${arrow('prepare-plan','M208 97 H250',plannerInputState,!plannedHere&&plannerStatus!=='running')}${arrow('plan-draft','M438 97 H480',planAdopted?draft.state:'idle',!planAdopted)}${!planAdopted?arrow('prepare-draft','M119 156 V182 Q119 190 127 190 H458 Q466 190 466 182 V105 Q466 97 474 97 H480',draft.state):''}${arrow('draft-extract','M579 156 V236',extract.state==='idle'?draft.state:extract.state)}${arrow('extract-review','M490 305 H448',check.state==='idle'?extract.state:check.state)}${arrow('review-save','M260 305 H218',save==='idle'?check.state:save)}</svg>${nodes.map((n,i)=>`<button class="graph-node ${E(n.state)} ${inspectedStage===n.id?'selected':''}" data-act="inspect-stage" data-stage="${n.id}" aria-pressed="${inspectedStage===n.id}" style="left:${n.x}px;top:${n.y}px"><span class="node-heading"><span class="graph-node-icon">${nodeIcon(n.icon)}</span><span class="node-state">${({complete:'已完成',running:'执行中',failed:'失败',unknown:'待确认',ready:'已就绪',skipped:'可选',stale:'待更新',idle:'等待'})[n.state]||'等待'}</span></span><strong>${E(n.title)}</strong><span class="node-detail">${E(n.detail)}</span></button>`).join('')}${!planAdopted?'<span class="canvas-bypass-label">直接起草</span>':''}<span class="canvas-path-label" style="left:276px;top:388px">${count} 个场景按顺序执行</span></div></div></div><div class="canvas-foot"><span>${typeof matchMedia==='function'&&matchMedia('(max-width:760px)').matches?'横向滑动查看完整流程':'点击节点查看提示词与结果'}</span><span data-effective-model>${auto.requestModel?E(auto.requestModel):form.model?E(form.model):defaultModel?E(defaultModel):'尚未选择模型'}</span></div>${inspectedStage?stageInspector():''}${auto.notice?`<div class="run-notice ${['failed','unknown'].includes(auto.status)?'note warn':''}" role="status">${E(auto.notice)}</div>`:''}</section>`;
}
function nodeIcon(name){const paths={idea:'<path d="M9 18h6m-6 3h6M8.1 14.5a6 6 0 1 1 7.8 0c-.8.6-.9 1.5-.9 2.5H9c0-1-.1-1.9-.9-2.5Z"/>',plan:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',draft:'<path d="m14 4 6 6M4 20l5-1L21 7a2 2 0 0 0-4-4L5 15zM13 20h8"/>',extract:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="12" r="2"/><circle cx="6" cy="19" r="2"/><path d="m8 6 8 5m-8 7 8-5"/>',review:'<circle cx="10" cy="10" r="6"/><path d="m14.5 14.5 6 6M7 10l2 2 4-4"/>',save:'<path d="M5 3h12l4 4v14H3V3h2Z"/><path d="M7 3v6h10V3M7 21v-8h10v8"/>'};return `<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.draft}</svg>`}
function stageInspector(){
  const name=({prepare:'创作构思',plan:'场景规划',draft:'正文生成',extract:'事实提取',review:'独立审阅',save:'保存作品'})[inspectedStage];
  const groups=inspectedStage==='prepare'?[{stage:'起草输入',messages:ideaPreview?.messages||[]}]:inspectedStage==='plan'?[{stage:'规划输入',messages:planPreview?.messages||[]}]:auto.messages.filter(x=>x.kind===inspectedStage);
  let output='';
  if(inspectedStage==='prepare')output=`<p>${E(form.runMode==='scene'?form.instruction:form.idea)||'在创作设置中写下故事构思。'}</p>`;
  else if(inspectedStage==='plan')output=planResult?`<ol class="plan-list">${planResult.scenes.map(x=>`<li><strong>${E(x.title)}</strong><p>${E(x.goal)}</p></li>`).join('')}</ol>`:form.scenePlans?`<div class="text">${E(form.scenePlans)}</div>`:'<p class="small">场景规划是可选步骤。可在创作设置中填写计划，或让 AI 生成；未规划时将直接依据构思创作。</p>';
  else if(inspectedStage==='draft')output=candidate?`<div class="text">${E(candidate.text)}</div>`:auto.scenes.some(x=>x?.text)?auto.scenes.filter(x=>x?.text).map(x=>`<section class="node-output"><h3>第 ${E(x.index)} 幕</h3><div class="text">${E(x.text)}</div></section>`).join(''):'<p class="small">还没有生成正文。开始创作后，这里显示每个场景的实际返回结果。</p>';
  else if(inspectedStage==='extract')output=factsOutput();
  else if(inspectedStage==='review')output=reviewOutput();
  else output=auto.saved||runs.apply==='complete'?'<p>本次生成的场景已保存为作品草稿。</p><a href="consistency.html?view=write">打开正文编辑</a>':auto.draft?'<p>生成的候选正文需要你的确认。</p><button data-act="result-tab" data-tab="manuscript">查看正文并保存</button>':'<p class="small">正文生成后，可在正文页签中审阅并保存。</p>';
  return `<div class="stage-inspector"><div class="section-title"><h3>${E(name)}</h3><button class="text-button" data-act="inspect-stage" data-stage="${E(inspectedStage)}">关闭详情</button></div><div class="inspector-tabs"><button data-act="inspector-tab" data-tab="output" class="${inspectorTab==='output'?'active':''}">内容与结果</button><button data-act="inspector-tab" data-tab="input" class="${inspectorTab==='input'?'active':''}">模型输入</button></div><div class="inspector-content">${inspectorTab==='input'?(groups.some(x=>x.messages.length)?groups.map(x=>`<h3>${E(x.stage)}</h3>${messagesView(x.messages)}`).join(''):'<p class="small">尚未发起此阶段的模型请求。可先预览提示词；实际执行后会显示完整输入。</p>'):output}</div></div>`;
}
function fitCanvas(){const viewport=document.querySelector('.graph-viewport');if(!viewport)return;canvasZoom=Math.max(.5,Math.min(1,(viewport.clientWidth-32)/700));render()}
function resultsPanel(){const tabs=[['manuscript','正文'],['facts','事实'],['review','审阅'],['prompts','提示词']];return `<section class="result-panel"><div class="result-nav" role="tablist" aria-label="查看创作结果">${tabs.map(([key,label])=>`<button id="result-tab-${key}" type="button" role="tab" aria-selected="${resultTab===key}" aria-controls="result-content" data-act="result-tab" data-tab="${key}" class="${resultTab===key?'active':''}">${label}${key==='facts'&&auto.scenes.some(x=>x?.candidates?.length)?`<span>${auto.scenes.reduce((n,x)=>n+(x?.candidates?.length||0),0)}</span>`:key==='review'&&auto.scenes.some(x=>x?.issues?.length)?`<span>${auto.scenes.reduce((n,x)=>n+(x?.issues?.length||0),0)}</span>`:''}</button>`).join('')}</div><div id="result-content" class="result-content" role="tabpanel" aria-labelledby="result-tab-${E(resultTab)}">${resultTab==='facts'?factsOutput():resultTab==='review'?reviewOutput():resultTab==='prompts'?promptOutput():manuscriptOutput()}</div></section>`}
function emptyResult(title,body){return `<div class="result-empty"><svg width="48" height="56" viewBox="0 0 48 56" fill="none" aria-hidden="true"><path d="M10 4h20l9 9v38H10V4Z" stroke="currentColor" stroke-width="1.5"/><path d="M30 4v10h9M18 24h14M18 31h14M18 38h9" stroke="currentColor" stroke-width="1.5"/></svg><h3>${E(title)}</h3><p>${E(body)}</p></div>`}
function manuscriptOutput(){
 const scenes=auto.scenes.filter(x=>x?.text);
 if(!scenes.length&&runs.apply==='complete')return `<div class="result-empty"><h3>草稿已保存</h3><p>本次创作已追加到当前场景。你可以继续编辑并保存正文版本。</p><a href="consistency.html?view=write">打开正文编辑</a></div>`;
 if(!scenes.length)return `<div>${candidate?`<article class="manuscript"><div class="manuscript-meta"><span>待作者审阅</span><span>${E(candidate.model||'')}</span></div><div class="prose">${E(candidate.text)}</div><button class="primary" data-act="apply" ${busy||pending||!sameInput()?'disabled':''}>追加到当前草稿</button></article>`:emptyResult('尚无候选正文','写下一段构思，开始创作。每个场景完成后，正文会出现在这里。')}</div>`;
 return `<div class="manuscript-actions"><span>${scenes.length} 幕 · ${scenes.reduce((n,x)=>n+x.text.length,0).toLocaleString('zh-CN')} 字</span><button class="text-button" data-act="copy-idea">复制正文</button></div>${scenes.map(x=>`<article class="manuscript"><div class="manuscript-meta"><span>第 ${E(x.index)} 幕</span><span>${E(x.model||'未提供模型名称')}</span></div><div class="prose">${E(x.text)}</div></article>`).join('')}<textarea id="idea-result" class="sr-only" readonly aria-label="全部候选正文">${E(scenes.map(x=>x.text).join('\n\n'))}</textarea>${auto.saved?'<div class="saved-result">已保存到作品。<a href="consistency.html?view=write">打开正文编辑</a></div>':`<div class="save-result"><h3>保存本次创作</h3><div class="field-pair"><label class="field">作品名称<input id="idea-project-name" maxlength="100" value="${E(form.projectName)}" placeholder="为故事取一个名字"></label><label class="field">首个场景名称<input id="idea-scene-title" maxlength="100" value="${E(form.sceneTitle)}" placeholder="如：第一封来信"></label></div><button class="primary" data-act="save-idea" ${busy||pending?'disabled':''}>保存为新作品草稿</button><p class="small">保存已收到的 ${scenes.length} 个场景。事实与审阅结果仍需确认。</p></div>`}`
}
function factsOutput(){const scenes=auto.scenes.filter(x=>x?.candidates?.length);if(!scenes.length)return emptyResult('事实与原文证据','正文生成后，AI 会提取人物、物品、时间与设定。这里显示候选事实，供你核对后采用。');return `<p class="output-note">以下是候选事实，尚未写入作品设定。</p>${scenes.map(x=>`<section class="result-group"><h3>第 ${E(x.index)} 幕</h3>${x.candidates.map(f=>`<article class="evidence-item"><strong>${E(f.statement)}</strong><blockquote>${E(f.evidence?.quote||f.quote||'未返回原文证据')}</blockquote></article>`).join('')}</section>`).join('')}`}
function reviewOutput(){const completed=auto.stages.some(x=>x.kind==='review'&&x.status==='complete');const scenes=auto.scenes.filter(x=>x?.issues?.length);if(!scenes.length)return review?reviewView():emptyResult(completed?'本次审阅未列出问题':'审阅意见与依据',completed?'这表示本次模型未发现问题。请结合正文判断，仍可能有遗漏。':'每个场景完成后会独立审阅。问题、原文依据与待确认事项会集中在这里。');return `<p class="output-note">${scenes.reduce((n,x)=>n+x.issues.length,0)} 条待审阅意见。请结合原文判断。</p>${scenes.map(x=>`<section class="result-group"><h3>第 ${E(x.index)} 幕</h3>${x.issues.map(i=>`<article class="evidence-item"><strong>${E(i.description)}</strong><blockquote>${E(i.evidence?.quote||i.quote||'未返回原文依据')}</blockquote></article>`).join('')}</section>`).join('')}`}
function promptOutput(){return `<div class="prompt-heading"><h3>控制每一步如何写</h3><p>分别调整写作、事实提取和审阅的要求。</p></div><fieldset ${busy?'disabled':''}>${promptEditors()}</fieldset><button data-act="idea-preview" ${busy||pending?'disabled':''}>预览完整提示词</button>${ideaPreview?`<details class="prompt-preview" open><summary>本次输入 · ${E(ideaPreview.model||'默认模型')}</summary><h3>起草正文</h3>${messagesView(ideaPreview.messages)}${Object.entries(ideaPreview.analysisTemplates||{}).map(([name,msgs])=>`<details><summary>${E(({extract:'事实抽取模板',review:'审阅模板'})[name]||name)}</summary><p class="small">生成的正文将在执行时填入模板。</p>${messagesView(Array.isArray(msgs)?msgs:[])}</details>`).join('')}</details>`:''}${auto.messages.length?`<details class="prompt-preview"><summary>本次实际发送的输入</summary>${auto.messages.map(x=>`<section class="result-group"><h3>${E(x.stage)}</h3>${messagesView(x.messages)}</section>`).join('')}</details>`:''}`}
function eventHistory(){return `<details class="event-history" data-detail-key="event-history"><summary>运行记录${events.length?' · '+events.length+' 条':''}</summary><ol class="timeline">${events.map(x=>`<li><time>${E(x.time)}</time><span>${E(x.message)}</span></li>`).join('')||'<li>尚未发起请求。</li>'}</ol><p class="small">记录保存在当前页面，刷新后清空。</p></details>`}
function ideaPanel(){return `<div class="brief-heading"><h2 id="brief-title">创作设置</h2><button class="text-button brief-collapse" data-act="toggle-brief" type="button" aria-label="收起创作设置">收起</button></div><fieldset ${busy?'disabled':''}><div class="mode-switch" aria-label="创作方式"><button type="button" data-act="set-mode" data-mode="idea" aria-pressed="${form.runMode==='idea'}" class="${form.runMode==='idea'?'active':''}">新建故事</button><button type="button" data-act="set-mode" data-mode="scene" aria-pressed="${form.runMode==='scene'}" class="${form.runMode==='scene'?'active':''}">续写场景</button></div>${form.runMode==='scene'?sceneContext():`<label class="field idea-field">故事构思<textarea id="idea" maxlength="4000" placeholder="从一个想法开始创作。一个人、一种处境，或者一个你一直想写的故事。">${E(form.idea)}</textarea></label>`}${modelControl('idea-model',form.model)}<div class="scene-count"><label for="idea-count">本次写几个场景</label><select id="idea-count">${[1,2,3,4,5].map(n=>`<option value="${n}" ${Number(form.sceneCount)===n?'selected':''}>${n} 个</option>`).join('')}</select></div><div class="brief-actions"><button class="primary start-button" data-act="start-creation" ${busy||pending?'disabled':''}>${auto.status==='running'?'正在创作…':auto.draft?'再次创作':'开始创作'}</button><button class="text-button" data-act="preview-prompts" ${busy||pending?'disabled':''}>预览提示词</button></div><p class="brief-help">${form.sceneCount===1?'每次创作依次起草、提取事实和审阅。':`本次最多 ${Number(form.sceneCount)*3} 次模型调用。`}调用按用量计费，请保持页面打开。</p>${planningPanel()}<button class="prompt-shortcut" type="button" data-act="result-tab" data-tab="prompts"><span>写作与审阅提示词</span><span>${form.writer||form.extract||form.reviewPrompt?'已自定义':'可编辑'}</span></button>${form.runMode==='scene'?`<details class="scene-tools" data-detail-key="scene-tools"><summary>单独生成或检查当前场景</summary><p class="small">仅对选中场景操作，不启动连续创作。</p><button data-act="preview" ${busy||pending?'disabled':''}>预览当前场景输入</button>${preview?previewView(sameInput()):''}</details>`:''}${ideaPreview&&resultTab!=='prompts'?`<details class="quick-preview" data-detail-key="quick-preview"><summary>已准备的提示词</summary>${messagesView(ideaPreview.messages)}<button class="primary" data-act="auto-run" ${busy||pending?'disabled':''}>按此输入开始创作</button></details>`:''}</fieldset>`}
function planPayload(){if(!form.idea.trim())throw Error('请先填写故事构思');return {idea:form.idea.trim(),sceneCount:Number(form.sceneCount)||1,model:form.model.trim(),plannerPrompt:form.plannerPrompt}}
async function previewPlan(){let input;try{input=planPayload()}catch(e){toast(e.message);return}busy=true;plannerStatus='idle';render();try{let r=await fetch(base+'plan-preview',{method:'POST',headers:headers(),body:JSON.stringify(input)}),v=await r.json();if(!r.ok||typeof v.previewHash!=='string')throw Error(v.error||'规划预览失败');planPreview=v;planPreviewInput=input;planResult=null;log('已预览规划提示词；未调用模型')}catch(e){planPreview=null;toast(e.message||'规划预览失败')}finally{busy=false;render()}}
async function runPlan(){let input;try{input=planPayload()}catch(e){toast(e.message);return}if(!planPreview||JSON.stringify(input)!==JSON.stringify(planPreviewInput)){toast('构思、模型或规划指导已变化，请重新预览');return}busy=true;plannerStatus='running';render();try{let r;try{r=await fetch(base+'plan',{method:'POST',headers:headers(),body:JSON.stringify({...input,previewHash:planPreview.previewHash})})}catch{throw Error('未收到规划响应，模型可能已执行或计费，不会自动重试。')}let v;try{v=await r.json()}catch{throw Error('规划响应无法解析，模型可能已执行或计费，不会自动重试。')}if(!r.ok){let definite=r.status>=400&&r.status<500&&![408,409,429].includes(r.status)||r.status===503&&(v.error||'').includes('尚未配置');throw Error((v.error||'规划失败')+(definite?'':'；模型可能已执行或计费，不会自动重试。'))}if(!Array.isArray(v.scenes)||v.scenes.length!==input.sceneCount)throw Error('规划返回格式无效；模型可能已执行或计费。');planResult=v;plannerStatus='complete';log('已收到场景计划，等待作者审阅')}catch(e){plannerStatus='failed';toast(e.message||'结果未知，模型可能已执行或计费，不会自动重试。')}finally{busy=false;render()}}
function ideaPayload(){const plans=form.scenePlans.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(plans.length>form.sceneCount||plans.some(x=>x.length>1500))throw Error('场景计划不能多于场景数，每行最多 1500 字');const common={model:form.model.trim(),sceneCount:Number(form.sceneCount)||1,scenePlans:plans,prompts:{writer:form.writer,extract:form.extract,review:form.reviewPrompt}};if(form.runMode==='scene'){const r=revision();if(!r||!draftMatches(scene(),r))throw Error('请先选择场景并保存正文版本');if(!form.instruction.trim()||!form.moment.trim())throw Error('请填写写作要求与故事时点');return {mode:'scene',projectId,sceneId,revisionId:r.id,instruction:form.instruction.trim(),storyMoment:form.moment.trim(),perspective:form.perspective,pov:form.pov.trim(),factIds:form.factIds.slice(),...common}}if(!form.idea.trim())throw Error('请先填写故事构思');return {mode:'idea',idea:form.idea.trim(),instruction:'',...common}}
async function previewIdea(){let input;try{input=ideaPayload()}catch(e){toast(e.message);return}busy=true;render();try{let response=await fetch(base+'auto-preview',{method:'POST',headers:headers(),body:JSON.stringify(input)}),d=await response.json();if(!response.ok||typeof d.previewHash!=='string')throw Error(d.error||'预览失败');ideaPreview=d;ideaPreviewInput=input;log('作者预览了实际起草输入；未调用模型')}catch(e){ideaPreview=null;ideaPreviewInput=null;toast(e.message||'预览失败')}finally{busy=false;render()}}
async function runIdea(){if(auto.draft&&!auto.saved&&!confirm('当前候选尚未保存。重新开始会丢弃本页候选，确定继续？'))return;let input;try{input=ideaPayload()}catch(e){toast(e.message);return}if(!ideaPreview||JSON.stringify(input)!==JSON.stringify(ideaPreviewInput)){toast('构思、提示词或模型已变化，请重新预览');return}input={...input,previewHash:ideaPreview.previewHash};busy=true;resultTab='manuscript';runs={preview:'idle',draft:'idle',review:'idle',apply:'idle'};auto={status:'running',usedPlan:adoptedCurrentPlan(),sceneCount:input.sceneCount,stages:[],messages:[],draft:'',candidates:[],issues:[],scenes:[],notice:''};log('作者启动自动创作');render();let completed=false,received=false;try{const response=await fetch(base+'auto-run',{method:'POST',headers:headers(),body:JSON.stringify(input)});log(`自动创作：收到 HTTP ${response.status}`);if(!response.ok){let d=await response.json().catch(()=>({}));const err=Error(d.error||`请求失败（HTTP ${response.status}）`);err.definite=response.status>=400&&response.status<500||response.status===503&&(d.error||'').includes('尚未配置');throw err}if(!response.body)throw Error('没有收到执行事件，结果未知。');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';const accept=block=>{let kind='',data='';for(const line of block.split(/\r?\n/)){if(line.startsWith('event:'))kind=line.slice(6).trim();else if(line.startsWith('data:'))data+=line.slice(5).trim()}if(!kind||!data)return;let d;try{d=JSON.parse(data)}catch{throw Error('执行事件格式无效，结果未知。')}received=true;if(kind==='context_ready'){auto.notice=d.notice||'';auto.requestModel=d.model||input.model||defaultModel||'站点默认';auto.messages.push({stage:'起草上下文',messages:d.messages||[]});log('上下文已准备')}else if(kind==='stage_start'){auto.stages.push({label:`第 ${d.sceneIndex||1} 幕 · ${{draft:'起草',extract:'抽取事实',review:'审阅'}[d.stage]||d.stage}`,kind:d.stage,index:d.sceneIndex||1,status:'running',detail:'请求中'});auto.messages.push({stage:`第 ${d.sceneIndex||1} 幕 · ${{draft:'起草正文',extract:'提取事实',review:'独立审阅'}[d.stage]||d.stage}`,kind:d.stage,messages:d.messages||[]});log(`${d.stage} 请求已开始`)}else if(kind==='draft_ready'){let idx=d.sceneIndex||1;auto.draft=typeof d.text==='string'?d.text:'';auto.scenes[idx-1]={...(auto.scenes[idx-1]||{}),index:idx,text:auto.draft,model:d.model||'未提供'};let stage=auto.stages.findLast(x=>x.kind==='draft'&&x.index===idx);if(stage){stage.status='complete';stage.detail='已收到候选'}log('已收到候选正文')}else if(kind==='extract_ready'){let idx=d.sceneIndex||1;auto.candidates=Array.isArray(d.candidates)?d.candidates:[];auto.scenes[idx-1]={...(auto.scenes[idx-1]||{}),index:idx,candidates:auto.candidates,extractModel:d.model||'未提供'};let stage=auto.stages.findLast(x=>x.kind==='extract'&&x.index===idx);if(stage){stage.status='complete';stage.detail='已收到结果'}log('已收到事实候选')}else if(kind==='review_ready'){let idx=d.sceneIndex||1;auto.issues=Array.isArray(d.issues)?d.issues:[];auto.scenes[idx-1]={...(auto.scenes[idx-1]||{}),index:idx,issues:auto.issues,reviewModel:d.model||'未提供'};auto.notice=d.notice||auto.notice;let stage=auto.stages.findLast(x=>x.kind==='review'&&x.index===idx);if(stage){stage.status='complete';stage.detail='等待作者审阅'}log('已收到审阅结果')}else if(kind==='complete'){completed=true;auto.status='complete';auto.notice=d.notice||'结果需要作者审阅。';log('自动创作已完成，等待作者审阅')}else if(kind==='error'){completed=true;auto.status=d.uncertain?'unknown':'failed';auto.notice=(d.error||'执行未完成')+(d.notice?' '+d.notice:'');let stage=auto.stages.at(-1);if(stage?.status==='running'){stage.status=d.uncertain?'unknown':'failed';stage.detail=d.uncertain?'结果未知':'执行失败'}log(auto.notice)}render()};while(true){const part=await reader.read();if(part.done)break;buffer+=decoder.decode(part.value,{stream:true});let m;while((m=/\r?\n\r?\n/.exec(buffer))){const block=buffer.slice(0,m.index);buffer=buffer.slice(m.index+m[0].length);accept(block)}}buffer+=decoder.decode();if(!completed)throw Error('连接中断，模型是否已执行或产生费用无法确认；不会自动重试。')}catch(e){if(!completed){auto.status=e.definite?'failed':'unknown';for(const stage of auto.stages){if(stage.status==='running'){stage.status=auto.status;stage.detail=e.definite?'执行失败':'结果未知'}}auto.notice=(e.message||'无法取得结果')+(e.definite?'':'；模型是否执行或计费无法确认，不会自动重试。');log(auto.notice)}}finally{busy=false;render()}}
function previewView(compiled){return `<div id="context-safety" class="note ${compiled?'':'warn'}">${compiled?'已准备当前场景的输入。':'输入已变化，请重新预览。'}</div><p class="small">${E(preview.model||'尚未选择模型')} · 参考 ${preview.included?.length||0} 条事实</p><details><summary>参考事实与证据</summary>${(preview.included||[]).map(f=>`<article class="evidence-item"><strong>${E(f.statement)}</strong><blockquote>${E(f.source?.evidence||'')}</blockquote></article>`).join('')||'<p class="small">没有纳入事实。</p>'}${(preview.excluded||[]).length?`<p class="small">${preview.excluded.length} 条事实未采用。</p><details><summary>查看原因</summary>${preview.excluded.map(f=>`<p class="small">${E(f.reason)}</p>`).join('')}</details>`:''}</details><details><summary>完整起草输入</summary>${messagesView(preview.messages)}</details><details><summary>完整审阅输入</summary>${messagesView(preview.checkMessages)}</details><div class="actions"><button class="primary" data-act="draft" ${!compiled||busy||pending?'disabled':''}>生成候选正文</button><button data-act="review" ${!compiled||busy||pending?'disabled':''}>独立检查场景</button></div><p class="small">生成与检查会调用模型。候选需确认后保存。</p>`}
function reviewView(){let issues=review.issues||[];return `<div class="note warn">结果为 REVIEW，需要人工判断；未列出问题也不代表整书一致。</div><p class="small">模型：${E(review.model||'未提供')} · ${issues.length} 条问题</p><div class="records">${issues.map((x,i)=>`<article class="item"><p>${E(x.description)}</p><div class="text">${E(x.evidence?.quote||x.quote||'')}</div><p class="small">证据出现在正文 ${E(x.evidence?.occurrences??0)} 处 · 关联事实：${E((x.factIds||[]).join('、')||'无')}</p><button data-act="mark" data-index="${i}" ${checked.has(i)?'disabled':''}>${checked.has(i)?'本页已标记复核':'标记本页已复核'}</button></article>`).join('')||'<div class="empty">模型未列出问题；不代表没有遗漏。</div>'}</div><p class="small">复核标记只保存在当前页面，不会自动写入事实。</p>`}
function render(){
 const oldViewport=document.querySelector('.graph-viewport');
 const viewScroll=oldViewport?{left:oldViewport.scrollLeft,top:oldViewport.scrollTop}:null;
 const active=document.activeElement,focusId=active?.id,focusStage=active?.dataset?.stage;
 if(!archive){const signedOut=!account;root.innerHTML=studioShell(`<div class="canvas-page"><section class="canvas-entry"><div class="entry-symbol" aria-hidden="true">${nodeIcon('draft')}</div><h2>${signedOut?'让故事从这里开始':'暂时无法打开创作画布'}</h2><p>${signedOut?'写下构思，选择模型，查看正文、事实与审阅如何逐步完成。登录后继续你的创作。':E(loadError||'作品暂时无法读取，请重试。')}</p>${signedOut?'<a class="primary" href="/signin-with-chatgpt?return_to=%2Fapps%2Fnovel-studio%2Fcanvas.html" target="_top">登录并开始创作</a>':'<button data-act="reload">重新读取</button>'}</section></div>`);return}
 root.innerHTML=view();
 for(const detail of document.querySelectorAll('details[data-detail-key]'))detail.open=openDetails.has(detail.dataset.detailKey);
 refreshRunButtons();
 const nextViewport=document.querySelector('.graph-viewport');if(viewScroll&&nextViewport){nextViewport.scrollLeft=viewScroll.left;nextViewport.scrollTop=viewScroll.top}
 if(focusId)document.getElementById?.(focusId)?.focus?.({preventScroll:true});else if(focusStage)document.querySelector('[data-act=inspect-stage][data-stage='+focusStage+']')?.focus?.({preventScroll:true});
}
function persistForm(){if(!account)return;try{sessionStorage.setItem('novel-canvas-form:'+account,JSON.stringify({form,projectId,sceneId}));if(projectId)sessionStorage.setItem('novel-active-context:'+account,JSON.stringify({projectId,sceneId}))}catch{}}
function restoreForm(){try{const raw=JSON.parse(sessionStorage.getItem('novel-canvas-form:'+account)||'null');if(!raw||!raw.form||typeof raw.form!=='object')return;for(const key of Object.keys(form)){if(key==='model'&&sessionStorage.getItem('novel-model-choice:'+account)!==null)continue;const value=raw.form[key];if(key==='factIds'){if(Array.isArray(value))form.factIds=value.filter(x=>typeof x==='string').slice(0,40)}else if(key==='sceneCount'){if(Number.isInteger(value)&&value>=1&&value<=5)form.sceneCount=value}else if(typeof value==='string'&&value.length<=7500)form[key]=value}if(!['idea','scene'].includes(form.runMode))form.runMode='idea';if(!['omniscient','limited'].includes(form.perspective))form.perspective='omniscient';if(typeof raw.projectId==='string')projectId=raw.projectId;if(typeof raw.sceneId==='string')sceneId=raw.sceneId}catch{}}
function refreshRunButtons(){const primary=document.querySelector('[data-act=canvas-primary]');if(primary){primary.textContent=busy?'正在创作…':hasCreativeBrief()?'开始创作':form.runMode==='scene'?'填写续写要求':'填写构思';primary.disabled=busy||!!pending}let valid=false;try{valid=!!ideaPreview&&JSON.stringify(ideaPayload())===JSON.stringify(ideaPreviewInput)}catch{}for(const button of document.querySelectorAll('[data-act="auto-run"]'))button.disabled=!valid||busy||!!pending}

let loadError='';
function updateForm(e){let t=e.target;if(t.id==='instruction')form.instruction=t.value;else if(t.id==='moment')form.moment=t.value;else if(t.id==='pov')form.pov=t.value;else if(t.id==='model'||t.id==='idea-model'){form.model=t.value;let peer=document.getElementById(t.id==='model'?'idea-model':'model');if(peer)peer.value=t.value;try{sessionStorage.setItem('novel-model-choice:'+account,form.model)}catch{}syncModelControls()}else if(t.id==='idea')form.idea=t.value;else if(t.id==='idea-writer')form.writer=t.value;else if(t.id==='idea-extract')form.extract=t.value;else if(t.id==='idea-review')form.reviewPrompt=t.value;else if(t.id==='idea-plans')form.scenePlans=t.value;else if(t.id==='planner-prompt')form.plannerPrompt=t.value;else if(t.id==='idea-project-name')form.projectName=t.value;else if(t.id==='idea-scene-title')form.sceneTitle=t.value;else return;persistForm();refreshRunButtons(); if(preview){const valid=sameInput();const btns=document.querySelectorAll('[data-act="draft"],[data-act="review"],[data-act="apply"]');btns.forEach(b=>b.disabled=!valid||busy||!!pending);let note=document.querySelector('#context-safety');if(note){note.textContent=valid?(preview.notice||'请人工审阅上下文。'):'表单已变化，请重新预览后再调用模型。';note.className=valid?'note':'note warn'}}}
root.addEventListener('input',updateForm);
root.addEventListener('toggle',event=>{const detail=event.target;if(!detail.dataset?.detailKey)return;if(detail.open)openDetails.add(detail.dataset.detailKey);else openDetails.delete(detail.dataset.detailKey)},true);
root.addEventListener('keydown',event=>{const tab=event.target.closest?.('[role=tab][data-tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const tabs=['manuscript','facts','review','prompts'],index=tabs.indexOf(tab.dataset.tab);resultTab=tabs[event.key==='Home'?0:event.key==='End'?3:(index+(event.key==='ArrowRight'?1:3))%4];render();document.getElementById?.('result-tab-'+resultTab)?.focus?.()});
root.addEventListener('change',e=>{let t=e.target;if(t.dataset?.modelPicker){const input=document.getElementById(t.dataset.modelPicker);if(t.value==='__manual__'){if(input){const detail=input.closest?.('details');if(detail)detail.open=true;input.focus?.()}return}if(input)input.value=t.value;updateForm({target:{id:t.dataset.modelPicker,value:t.value}});return}if(t.id==='idea-mode'){form.runMode=t.value==='scene'?'scene':'idea';persistForm();ideaPreview=null;ideaPreviewInput=null;render()}else if(t.id==='idea-count'){form.sceneCount=Number(t.value)||1;persistForm();refreshRunButtons();render()}else if(t.id==='project'){projectId=t.value;sceneId=project()?.scenes[0]?.id||'';form.factIds=[];invalidate();ideaPreview=null;ideaPreviewInput=null;persistForm();log('作者切换作品');render()}else if(t.id==='scene'){sceneId=t.value;invalidate();ideaPreview=null;ideaPreviewInput=null;persistForm();log('作者切换场景');render()}else if(t.id==='perspective'){form.perspective=t.value;persistForm();refreshRunButtons();render();if(preview){const valid=sameInput();const btns=document.querySelectorAll('[data-act="draft"],[data-act="review"],[data-act="apply"]');btns.forEach(b=>b.disabled=!valid||busy||!!pending);let note=document.querySelector('#context-safety');if(note){note.textContent=valid?(preview.notice||'请人工审阅上下文。'):'表单已变化，请重新预览后再调用模型。';note.className=valid?'note':'note warn'}}}else if(t.dataset.fact){form.factIds=t.checked?[...form.factIds,t.dataset.fact]:form.factIds.filter(x=>x!==t.dataset.fact);persistForm();refreshRunButtons();if(preview){const valid=sameInput();const btns=document.querySelectorAll('[data-act="draft"],[data-act="review"],[data-act="apply"]');btns.forEach(b=>b.disabled=!valid||busy||!!pending);let note=document.querySelector('#context-safety');if(note){note.textContent=valid?(preview.notice||'请人工审阅上下文。'):'表单已变化，请重新预览后再调用模型。';note.className=valid?'note':'note warn'}}}});
async function sendPending(){if(!pending||busy)return;busy=true;runs.apply='running';let response;try{const task=fetch(base+'canon',{method:'POST',headers:headers(),body:JSON.stringify(pending)});log('草稿保存：已发起请求');render();response=await task;let d=await response.json().catch(()=>null);log(`草稿保存：收到 HTTP ${response.status}`);if(!d||response.status>=500||response.status===408||response.status===429||response.status===401||response.status===403)throw Error(d?.error||'结果尚未确认，请重试相同命令。');if(!response.ok){pending=null;sessionStorage.removeItem(sessionKey());runs.apply='failed';throw Error(d.error||'保存未成功');}if(!d.state||!Number.isSafeInteger(d.version))throw Error('回执格式无效，请重试相同命令。');archive=d.state;version=d.version;if(pending.command?.type==='create_project_with_scene_drafts'){projectId=pending.command.projectId;sceneId=pending.command.scenes[0].sceneId;auto.saved=true;persistForm();auto.notice='已保存为新作品草稿；请在创作工作台审阅并保存版本。'}pending=null;sessionStorage.removeItem(sessionKey());runs.apply='complete';candidate=null;log(d.receipt?.replayed?'服务端返回原操作回执，未重复写入':'草稿已由服务端确认保存');toast('已保存到草稿；请回工作台审阅与保存版本。')}catch(e){runs.apply='failed';log(pending?'草稿保存：结果未确认，可恢复待确认操作':`草稿保存：${e.message}`);toast(e.message||'操作结果尚未确认')}finally{busy=false;render()}}
root.addEventListener('click',async e=>{let b=e.target.closest('[data-act]');if(!b)return;let action=b.dataset.act;
if(action==='result-tab'){if(['manuscript','facts','review','prompts'].includes(b.dataset.tab)){resultTab=b.dataset.tab;render();document.getElementById?.('result-tab-'+resultTab)?.focus?.()}return}
if(action==='inspect-stage'){inspectedStage=inspectedStage===b.dataset.stage?'':b.dataset.stage;inspectorTab='output';render();return}
if(action==='inspector-tab'){inspectorTab=b.dataset.tab==='input'?'input':'output';render();return}
if(action==='toggle-brief'){briefCollapsed=!briefCollapsed;render();return}
if(action==='zoom-in'||action==='zoom-out'){canvasZoom=Math.max(.5,Math.min(1.5,canvasZoom+(action==='zoom-in'?.1:-.1)));render();return}
if(action==='zoom-fit'){fitCanvas();return}
if(busy)return;
if(action==='canvas-primary'){if(pending)return;if(!hasCreativeBrief()){briefCollapsed=false;render();const target=document.getElementById?.(form.runMode==='scene'?'instruction':'idea');target?.focus?.();return}action='start-creation'}
if(action==='set-mode'){form.runMode=b.dataset.mode==='scene'?'scene':'idea';ideaPreview=null;ideaPreviewInput=null;persistForm();render();return}
if(action==='reload'){loadError='';try{await load();render()}catch(err){loadError=err.message;render()}return}
if(action==='preview-prompts'){resultTab='prompts';await previewIdea();return}
if(action==='start-creation'){if(pending)return;await previewIdea();let current;try{current=ideaPayload()}catch{return}if(ideaPreview&&JSON.stringify(current)===JSON.stringify(ideaPreviewInput))await runIdea();return}
if(action==='refresh-models'){await refreshModels();return}
if(action==='plan-preview'){await previewPlan();return}
if(action==='plan-run'){await runPlan();return}
if(action==='plan-apply'){if(!planResult?.scenes)return;let current;try{current=planPayload()}catch(e){toast(e.message);return}if(JSON.stringify(current)!==JSON.stringify(planPreviewInput)){toast('构思、模型或幕数已变化，请重新规划');return}form.scenePlans=planResult.scenes.map(x=>`${x.title}：${x.goal}`.replace(/[\r\n]+/g,' ')).join('\n');ideaPreview=null;ideaPreviewInput=null;persistForm();render();return}
if(action==='idea-preview'){await previewIdea();return}
if(action==='auto-run'){await runIdea();return}
if(action==='save-idea'){if(auto.saved){toast('本次创作已经保存');return}if(!auto.draft||!form.projectName.trim()||!form.sceneTitle.trim()){toast('请填写作品名称和场景名称');return}let drafts=auto.scenes.filter(x=>x?.text).map((x,i)=>({sceneId:crypto.randomUUID(),title:form.sceneTitle.trim().slice(0,94)+(auto.scenes.length>1?` · ${i+1}`:''),body:x.text}));if(!confirm(`将已收到的 ${drafts.length} 个候选保存为新作品草稿？不会自动确认事实。`))return;pending={commandId:crypto.randomUUID(),expectedVersion:version,command:{type:'create_project_with_scene_drafts',projectId:crypto.randomUUID(),name:form.projectName.trim(),description:'',scenes:drafts}};try{sessionStorage.setItem(sessionKey(),JSON.stringify(pending))}catch{pending=null;toast('无法保存恢复记录，本次未发送。');return}log('作者确认创建作品草稿');await sendPending();return}
if(action==='copy-idea'){const el=document.getElementById('idea-result');if(el){el.focus();el.select();try{await navigator.clipboard.writeText(auto.scenes.filter(x=>x?.text).map(x=>x.text).join('\n\n'));toast('候选正文已复制')}catch{toast('已选中正文，请使用复制快捷键')}}return}
if(action==='preview'){form.runMode='scene';let r=revision();if(!r||!draftMatches(scene(),r)){toast('请先保存草稿和正文版本');return}if(!form.instruction.trim()||!form.moment.trim()){toast('请填写写作要求和数字故事时点');return}if(form.factIds.length>40){toast('最多选择 40 条事实');return}if(form.perspective==='limited'&&!form.pov.trim()){toast('限知视角需要填写人物名称');return}let input={projectId,sceneId,revisionId:r.id,instruction:form.instruction.trim(),storyMoment:form.moment.trim(),perspective:form.perspective,pov:form.pov.trim(),factIds:form.factIds.slice(),model:form.model.trim()};busy=true;runs.preview='running';preview=null;candidate=null;review=null;checked.clear();runs.draft='idle';runs.review='idle';runs.apply='idle';log('作者发起上下文预览');try{preview=await request('context',input,'上下文预览');if(typeof preview.previewHash!=='string'||!Array.isArray(preview.messages)||!Array.isArray(preview.checkMessages)||!Array.isArray(preview.included)||!Array.isArray(preview.excluded)||preview.revisionId!==input.revisionId){preview=null;throw Error('预览响应缺少必要字段。')}previewInput=input;runs.preview='complete';log(`上下文已编译：纳入 ${preview.included?.length||0} 条，排除 ${preview.excluded?.length||0} 条`)}catch(err){runs.preview='failed';log(`上下文预览失败：${err.message}`);toast(err.message)}finally{busy=false;render()}return}
if(action==='draft'||action==='review'){if(!sameInput()){toast('输入已变化，请重新预览');return}busy=true;runs[action]='running';if(action==='draft')candidate=null;else{review=null;checked.clear()}log(action==='draft'?'作者发起候选生成':'作者发起独立检查');try{let d=await request(action,{...previewInput,previewHash:preview.previewHash},action==='draft'?'候选生成':'独立检查');if(d.previewHash!==preview.previewHash||d.stateVersion!==version||d.revisionId!==previewInput.revisionId){const err=Error('返回结果与当前预览不一致；模型可能已执行或产生费用，请重新读取。');err.unknown=true;throw err;}if(action==='draft'){resultTab='manuscript';if(typeof d.text!=='string'||!d.text.trim()){const err=Error('模型没有返回有效候选；本次请求可能产生费用。');err.unknown=true;throw err;}candidate=d;log('已收到候选，等待作者审阅')}else{resultTab='review';if(!Array.isArray(d.issues)){const err=Error('检查响应缺少问题列表；本次请求可能产生费用。');err.unknown=true;throw err;}review=d;log(`已收到检查结果：${d.issues.length} 条待审问题`)}runs[action]='complete'}catch(err){runs[action]=err.unknown?'unknown':'failed';log(`${action==='draft'?'候选生成':'独立检查'}${err.unknown?'结果未知':'失败'}：${err.message}`);toast(err.message)}finally{busy=false;render()}return}
if(action==='mark'){let i=Number(b.dataset.index);if(!review?.issues?.[i])return;checked.add(i);runs.apply='complete';log(`作者在本页标记问题 ${i+1} 已复核`);render();return}
if(action==='apply'){let s=scene(),r=revision();if(!candidate||!sameInput()||candidate.stateVersion!==version||candidate.revisionId!==r?.id||!draftMatches(s,r)){toast('档案或场景已变化，请重新预览。');return}if(!confirm('将候选正文追加到当前场景草稿？已保存版本与事实不会自动修改。'))return;pending={commandId:crypto.randomUUID(),expectedVersion:version,command:{type:'save_draft',projectId,sceneId,title:s.title,body:s.draft+'\n\n'+candidate.text}};try{sessionStorage.setItem(sessionKey(),JSON.stringify(pending))}catch{pending=null;toast('无法保存恢复记录，本次未发送。');return}log('作者确认追加候选到草稿');await sendPending();return}
if(action==='retry'){log('作者重试待确认的保存操作');await sendPending()}
});
document.addEventListener?.('visibilitychange',()=>{if(document.visibilityState==='visible'&&!busy&&account)void refreshModels()});
let approvedLeave=false;
function hasUnsavedResults(){return !!(busy||pending||candidate||(auto.draft&&!auto.saved))}
window.HubBeforeLeave=async()=>{persistForm();if(hasUnsavedResults()&&!confirm(busy?'创作正在执行。离开后无法继续接收结果，确定离开吗？':'本次生成的内容尚未全部保存，确定离开吗？'))return false;approvedLeave=true;return true};
window.HubCancelLeave=()=>{approvedLeave=false};
window.addEventListener('beforeunload',e=>{if(!approvedLeave&&hasUnsavedResults()){e.preventDefault();e.returnValue=''}});
try{let r=await fetch('/api/hub/session',{cache:'no-store'}),id=await r.json();if(!r.ok||!id.authenticated||!id.userId)throw Error('请先使用工作台账号登录。');account=id.userId;try{form.model=sessionStorage.getItem('novel-model-choice:'+account)||''}catch{}try{pending=JSON.parse(sessionStorage.getItem(sessionKey())||'null')}catch{throw Error('无法读取待确认操作，已停止。')}restoreForm();try{const context=JSON.parse(sessionStorage.getItem('novel-active-context:'+account)||'null');if(context&&typeof context.projectId==='string'){projectId=context.projectId;sceneId=typeof context.sceneId==='string'?context.sceneId:''}}catch{}await load();try{let mr=await fetch(base+'model-status',{cache:'no-store'});let md=await mr.json();if(mr.ok&&typeof md.model==='string')defaultModel=md.model}catch{}log('已读取当前账号的服务端档案');render();void refreshModels()}catch(e){loadError=e.message||'请求失败';render()}
})();
